// PART 1 — Individuals. Tax year 2025 law (2026–27 SEE window).
// F(part, domain, front, back)   Q(part, domain, level, stem, correct, [wrong...], explanation)
// Domains: 1 Preliminary work & taxpayer data · 2 Income & assets · 3 Deductions & credits · 4 Taxation · 5 Advising the individual · 6 Specialized returns

// ---------- Domain 1: Preliminary work, filing status, dependents ----------
F(1,1,"2025 standard deduction: Single or MFS","$15,750 (OBBBA amount; the earlier-announced $15,000 is wrong for 2025)");
F(1,1,"2025 standard deduction: MFJ or QSS","$31,500");
F(1,1,"2025 standard deduction: Head of Household","$23,625");
F(1,1,"2025 additional standard deduction for age 65+ or blind","$1,600 per condition for married taxpayers (MFJ, MFS, QSS); $2,000 per condition for Single or HOH");
F(1,1,"2025 standard deduction for someone claimed as a dependent","Greater of $1,350 or earned income + $450, but not more than the regular standard deduction");
F(1,1,"Gross income filing requirement for a married person filing separately","$5 of gross income");
F(1,1,"Self-employment filing trigger","Net earnings from self-employment of $400 or more");
F(1,1,"Church employee filing trigger","Church employee income of $108.28 or more");
F(1,1,"Date that determines marital status for the year","December 31 (if a spouse died during the year, you are treated as married for the whole year)");
F(1,1,"Qualifying Surviving Spouse: how long?","The 2 tax years after the year the spouse died, if you have a dependent child living with you and did not remarry. Year of death itself: MFJ allowed");
F(1,1,"Head of Household: cost-of-home test","Paid more than half the cost of keeping up a home for the year");
F(1,1,"Costs that count toward keeping up a home","Rent, mortgage interest, property taxes, home insurance, repairs, utilities, food eaten in the home. NOT clothing, education, medical care, vacations, life insurance, transportation, or mortgage principal");
F(1,1,"'Considered unmarried' for HOH: requirements","File a separate return; paid over half the home's cost; spouse did not live in the home during the last 6 months of the year; home was the main home of your child (whom you can claim, or could but for Form 8332) for over half the year");
F(1,1,"Qualifying child: the 5 tests","Relationship, Age, Residency (over half the year), Support (child did not provide over half own support), Joint return (child generally didn't file MFJ). Plus the citizenship test");
F(1,1,"Qualifying child age test","Under 19 at year end, or under 24 if a full-time student, and younger than you (or your spouse if MFJ). Any age if permanently and totally disabled");
F(1,1,"Full-time student definition","Enrolled full time for some part of each of 5 calendar months during the year");
F(1,1,"Qualifying relative: the 4 tests","Not a qualifying child of anyone; lives with you all year OR is a listed relative; gross income under $5,200 (2025); you provide over half of support");
F(1,1,"2025 qualifying relative gross income limit","Less than $5,200 (nontaxable Social Security doesn't count)");
F(1,1,"Multiple support agreement","Form 2120. No one provides over half, but a group together does; the person claiming must have provided over 10%; others who gave over 10% sign statements");
F(1,1,"Form 8332","Custodial parent releases the claim to the child to the noncustodial parent. Transfers ONLY the child tax credit/credit for other dependents and the dependency claim, NOT HOH, EIC, or the dependent care credit");
F(1,1,"Custodial parent definition","The parent the child lived with for the greater number of nights during the year (if equal, the parent with the higher AGI)");
F(1,1,"Tie-breaker: two parents who don't file jointly both qualify","Parent with whom the child lived longer; if equal, the parent with higher AGI");
F(1,1,"Tie-breaker: parent vs. non-parent","The parent claims. A non-parent can claim only if the parent doesn't AND the non-parent's AGI is higher than any parent's");
F(1,1,"Citizenship test for dependents","U.S. citizen, U.S. national, U.S. resident alien, or resident of Canada or Mexico (adopted child living with a U.S. citizen also qualifies)");
F(1,1,"Can a dependent claim another dependent?","No. If you can be claimed as a dependent, you cannot claim any dependents");
F(1,1,"Nonresident alien spouse: how to file jointly","Elect to treat the spouse as a U.S. resident (§6013(g)); then worldwide income of both is taxed");
F(1,1,"Form W-7","Application for an ITIN (Individual Taxpayer Identification Number)");
F(1,1,"Form W-7A","Application for an ATIN (Adoption Taxpayer Identification Number) for a child being adopted");
F(1,1,"Form 8867 covers which credits/status?","Paid preparer due diligence for EITC, CTC/ACTC/ODC, AOTC, and Head of Household filing status");
F(1,1,"Temporary absences and the residency test","Time away for school, illness, business, vacation, military service or detention counts as time lived in the home");
F(1,1,"Child born or died during the year: residency","Treated as having lived with you all year if your home was the child's home the entire time the child was alive");

Q(1,1,1,"Which filing status has a 2025 standard deduction of $23,625?","Head of Household",["Single","Married Filing Jointly","Qualifying Surviving Spouse"],"2025 OBBBA amounts: Single/MFS $15,750, HOH $23,625, MFJ/QSS $31,500.");
Q(1,1,1,"A married taxpayer filing separately must file a return if gross income is at least:","$5",["$400","$5,200","$15,750"],"MFS filers must file with gross income of $5 or more.");
Q(1,1,1,"The standard deduction is increased for individuals who are:","Age 65 or older and/or blind",["Retired from the military","Beneficiaries of a trust","Receiving unemployment compensation"],"IRC §63(f). Additional amount for 2025: $2,000 Single/HOH, $1,600 married.");
Q(1,1,1,"What is the 2025 gross income limit for a qualifying relative?","Less than $5,200",["Less than $5,050","Less than $4,700","Less than $15,750"],"The 2025 qualifying relative gross income limit is $5,200.");
Q(1,1,1,"A widow whose spouse died in 2025 and who has a dependent child may file as Qualifying Surviving Spouse for:","2026 and 2027",["2025 only","2025 and 2026","Any year until remarriage"],"In the year of death she may file MFJ. QSS is available for the 2 following years.");
Q(1,1,1,"Form 8332 allows a noncustodial parent to claim which benefit?","Child tax credit (and the dependency claim)",["Head of Household status", "Earned income credit", "Child and dependent care credit and head of household"],"Form 8332 releases only the dependency claim and CTC/ODC. HOH, EIC and dependent care stay with the custodial parent.");
Q(1,1,2,"Mia, 25, is a full-time graduate student who lived with her parents all year and had $3,000 of wages. Her parents provided over half her support. Which is correct?","Her parents may claim her as a qualifying relative",["Her parents may claim her as a qualifying child","No one can claim her because she is over 24","Her parents may claim her only with a multiple support agreement"],"She fails the qualifying child age test (under 24 if a student), but passes the qualifying relative tests: lived with them all year, gross income under $5,200, and over half support.");
Q(1,1,2,"Tom and his wife separated in March 2025 and lived apart the rest of the year. Tom paid over half the cost of the home where his 8-year-old son lived all year. They did not divorce. Tom's best filing status is:","Head of Household",["Single","Married Filing Separately","Qualifying Surviving Spouse"],"Tom is 'considered unmarried': spouse not in the home the last 6 months, he paid over half the home's cost, and his qualifying child lived there over half the year.");
Q(1,1,2,"A divorced couple's child lived with the mother 200 nights and the father 165 nights. The mother signs Form 8332. Which can the father claim?","The child tax credit for the child",["Head of Household status based on the child","The earned income credit for the child","The child and dependent care credit"],"The mother is the custodial parent. Form 8332 transfers only the dependency claim and CTC/ODC.");
Q(1,1,2,"Four siblings support their mother. Ann pays 35%, Ben 30%, Carl 25%, and Dana 10%. Under a multiple support agreement, who can claim the mother?","Ann, Ben, or Carl",["Ann only","Any of the four","No one, because no one paid over 50%"],"Each person claiming must have contributed over 10%. Dana paid exactly 10%, which is not over 10%.");
Q(1,1,2,"Which expense counts toward the cost of keeping up a home for Head of Household status?","Utilities",["Clothing","Medical care","Mortgage principal"],"Rent, mortgage interest, taxes, insurance, repairs, utilities and food eaten at home count. Principal, clothing, education and medical do not.");
Q(1,1,3,"Grandma (AGI $40,000) and her daughter (AGI $30,000) both live with the daughter's 6-year-old son all year. The daughter does not claim the child. Who may claim him?","Grandma, because her AGI is higher than the parent's",["Only the daughter, because she is the child's parent", "Neither, because both are eligible", "Grandma, but only with Form 8332"],"A non-parent may claim a qualifying child when the parent does not claim the child and the non-parent's AGI is higher than any parent's AGI.");
Q(1,1,3,"Leo, 17, is a dependent with $3,200 of wages and $600 of interest in 2025. What is his standard deduction?","$3,650",["$1,350","$3,800","$15,750"],"Greater of $1,350 or earned income + $450 = $3,200 + $450 = $3,650. Unearned income is not added.");
Q(1,1,3,"Which person does NOT pass the qualifying child age test for 2025?","A 20-year-old who took two night classes and works full time",["A 23-year-old full-time student","An 18-year-old high school graduate who works","A 30-year-old who is permanently and totally disabled"],"The 20-year-old is over 18 and is not a full-time student. The 18-year-old qualifies because under 19 is enough.");

// ---------- Domain 2: Income and assets ----------
F(1,2,"Social Security: provisional income formula","Modified AGI (including tax-exempt interest and excluded foreign income) + 50% of Social Security benefits");
F(1,2,"Social Security base amounts","$25,000 Single/HOH/QSS and MFS who lived apart all year; $32,000 MFJ; $0 for MFS who lived with spouse at any time during the year");
F(1,2,"Maximum % of Social Security benefits that can be taxable","85%");
F(1,2,"Second-tier Social Security thresholds (85% tier)","$34,000 Single/HOH; $44,000 MFJ");
F(1,2,"Alimony: pre-2019 vs post-2018 divorce agreements","Executed before 2019: deductible by payer, taxable to recipient. Executed after 2018 (or modified to adopt new rules): neither deductible nor taxable");
F(1,2,"Child support","Never taxable to the recipient and never deductible by the payer");
F(1,2,"Life insurance proceeds paid because of death (§101)","Generally excluded from income. Interest paid on the proceeds is taxable");
F(1,2,"Gifts and inheritances (§102)","Excluded from the recipient's income. Income later earned from the property is taxable");
F(1,2,"Scholarships: what is tax-free?","For a degree candidate: tuition, fees, and required books, supplies and equipment. Room, board and travel paid by a scholarship are taxable");
F(1,2,"Unemployment compensation (2025)","Fully taxable; reported on Form 1099-G");
F(1,2,"State income tax refund: taxable?","Taxable only to the extent you itemized and the deduction gave a tax benefit in the prior year (tax benefit rule)");
F(1,2,"Gambling winnings and losses (2025)","All winnings are income. Losses are an itemized deduction limited to winnings (100% for 2025; the 90% limit starts in 2026)");
F(1,2,"Qualified dividend holding period","Stock held more than 60 days in the 121-day period beginning 60 days before the ex-dividend date");
F(1,2,"2025 0% long-term capital gain rate applies up to","Taxable income of $48,350 Single/MFS; $64,750 HOH; $96,700 MFJ");
F(1,2,"2025 20% long-term capital gain rate starts above","$533,400 Single; $566,700 HOH; $600,050 MFJ; $300,000 MFS");
F(1,2,"Maximum rates on collectibles gain and unrecaptured §1250 gain","Collectibles 28%; unrecaptured §1250 gain 25%");
F(1,2,"Capital loss deduction limit","$3,000 per year against ordinary income ($1,500 MFS). Excess carries forward indefinitely, keeping its short/long-term character");
F(1,2,"Long-term holding period","More than 1 year");
F(1,2,"Wash sale rule (§1091)","Loss disallowed if substantially identical stock is bought within 30 days before or after the sale. Disallowed loss is added to the new shares' basis, and the holding period carries over");
F(1,2,"Basis of gifted property","For gain: donor's adjusted basis (carryover). For loss: lower of donor's basis or FMV at gift. Sale price between the two = no gain or loss");
F(1,2,"Basis of inherited property (§1014)","FMV at date of death (or alternate valuation date 6 months later if elected). Holding period is always long-term");
F(1,2,"Home sale exclusion (§121) amounts","$250,000 ($500,000 MFJ if either spouse meets ownership and both meet use)");
F(1,2,"Home sale exclusion tests","Owned and used as main home for 2 of the 5 years before the sale; exclusion not used in the prior 2 years");
F(1,2,"Home sale: reduced exclusion","Available if the 2-year tests are not met because of a change in place of employment, health, or unforeseen circumstances. Prorated by months qualified / 24");
F(1,2,"Home sale gain that can't be excluded","Depreciation claimed after May 6, 1997 (taxed up to 25%) and gain allocated to nonqualified use after 2008");
F(1,2,"Cancellation of debt: main exclusions (§108)","Bankruptcy; insolvency (to the extent insolvent); qualified principal residence indebtedness; qualified farm debt; qualified real property business debt. Reported on Form 1099-C, exclusions on Form 982");
F(1,2,"Rental of a home for fewer than 15 days","Rental income is not reported and rental expenses are not deducted");
F(1,2,"Vacation home: personal use test","Personal use exceeds the greater of 14 days or 10% of rental days → expenses limited to rental income");
F(1,2,"$25,000 rental loss allowance","For active participation in rental real estate. Phases out by 50% of MAGI over $100,000; gone at $150,000. Not available for MFS who lived together");
F(1,2,"Real estate professional test","More than 750 hours and more than half of personal services in real property trades in which you materially participate; rental losses then not automatically passive");
F(1,2,"Suspended passive losses","Carried forward; fully deductible when the entire interest is disposed of in a taxable transaction to an unrelated party");
F(1,2,"Excluded from income: personal physical injury damages","Compensatory damages for physical injury or sickness are excluded (§104). Punitive damages and interest are taxable");
F(1,2,"Group-term life insurance","Employer-paid coverage over $50,000 creates taxable income (imputed cost on W-2)");
F(1,2,"2025 qualified transportation fringe limit","$325 per month (parking, or transit and vanpool)");
F(1,2,"2025 health FSA salary reduction limit","$3,300 (carryover up to $660)");
F(1,2,"2025 dependent care assistance exclusion","$5,000 ($2,500 MFS). Rises to $7,500 in 2026 (trap)");
F(1,2,"Employer educational assistance exclusion","$5,250 per year (can include student loan payments)");
F(1,2,"Clergy housing allowance","Excluded from income tax (up to fair rental value) but subject to self-employment tax");
F(1,2,"10% early distribution penalty: age","Applies to distributions before age 59½ from IRAs and qualified plans, unless an exception applies (§72(t))");
F(1,2,"Penalty exceptions for IRAs only (not employer plans)","First-time homebuyer (up to $10,000 lifetime), qualified higher education expenses, health insurance premiums while unemployed");
F(1,2,"Penalty exceptions for employer plans only (not IRAs)","Separation from service in or after the year you turn 55 (50 for public safety employees); QDRO payments to an alternate payee");
F(1,2,"Penalty exceptions for both IRAs and plans","Death, disability, SEPP, medical expenses over 7.5% of AGI, IRS levy, qualified reservist, qualified birth/adoption up to $5,000, terminal illness, $1,000 emergency distribution, disaster distributions");
F(1,2,"SIMPLE IRA early withdrawal penalty","25% if within the first 2 years of participation (otherwise 10%)");
F(1,2,"Required minimum distribution (RMD) age","73 if born 1951–1959; 75 if born 1960 or later. First RMD may be delayed until April 1 of the following year");
F(1,2,"Penalty for missing an RMD","25% excise tax on the shortfall, reduced to 10% if corrected in a timely manner");
F(1,2,"Roth IRA qualified distribution","Account open 5 tax years AND age 59½, death, disability, or first-time homebuyer ($10,000)");
F(1,2,"Roth IRA ordering rules","Contributions first (always tax- and penalty-free), then conversions (first-in, first-out), then earnings");
F(1,2,"IRA rollover rules","Complete within 60 days; only one IRA-to-IRA (indirect) rollover per 12 months. Trustee-to-trustee transfers and conversions aren't limited");
F(1,2,"Mandatory withholding on plan distributions paid to you","20% on an eligible rollover distribution from an employer plan not directly rolled over");
F(1,2,"Inherited IRA: non-spouse designated beneficiary","Must empty the account by the end of the 10th year after death (10-year rule), unless an eligible designated beneficiary");
F(1,2,"Eligible designated beneficiaries (may stretch)","Surviving spouse; decedent's minor child (until 21); disabled; chronically ill; not more than 10 years younger than the decedent");
F(1,2,"Inherited IRA: 10% penalty?","No. Distributions due to death are exempt from the 10% penalty at any age");
F(1,2,"2025 HSA contribution limits","$4,300 self-only; $8,550 family; +$1,000 catch-up at age 55+");
F(1,2,"2025 HDHP minimum deductible","$1,650 self-only; $3,300 family");
F(1,2,"HSA nonqualified distribution","Taxable plus 20% penalty, unless age 65+, disabled, or death");
F(1,2,"529 plan: K-12 tuition limit for 2025","$10,000 per beneficiary per year (rises to $20,000 in 2026 — trap)");
F(1,2,"529 to Roth IRA rollover","Up to $35,000 lifetime; 529 open at least 15 years; subject to annual Roth contribution limit");
F(1,2,"Coverdell ESA contribution limit","$2,000 per beneficiary per year; beneficiary under 18 (unless special needs)");
F(1,2,"Savings bond interest exclusion (§135)","Series EE/I bonds issued after 1989 to an owner age 24+; used for qualified higher education expenses; phased out by MAGI; not available MFS");
F(1,2,"Net Investment Income Tax (NIIT) rate and thresholds","3.8% on the lesser of NII or MAGI over $200,000 Single/HOH, $250,000 MFJ/QSS, $125,000 MFS (not indexed)");
F(1,2,"NIIT does NOT apply to","Wages, self-employment income, IRA/qualified plan distributions, tax-exempt interest, excluded home sale gain, alimony");
F(1,2,"2025 Form 1099-K reporting threshold","More than $20,000 AND more than 200 transactions (OBBBA restored this retroactively)");
F(1,2,"2025 foreign earned income exclusion","$130,000 per qualifying individual");
F(1,2,"FEIE qualifying tests","Tax home in a foreign country AND either bona fide residence for a full tax year OR physical presence of 330 full days in any 12 consecutive months");
F(1,2,"Bartering income","FMV of goods or services received is income");
F(1,2,"Illegal income and embezzled funds","Taxable");
F(1,2,"Jury duty pay","Taxable; if turned over to the employer, deducted as an adjustment to income");
F(1,2,"Foster care payments","Generally excluded if from a state or qualified agency");
F(1,2,"Workers' compensation","Excluded from income");
F(1,2,"Prizes and awards","Taxable at FMV");

Q(1,2,1,"What is the maximum percentage of Social Security benefits that can be taxable?","85%",["50%","100%","75%"],"Up to 85% of benefits can be included in income.");
Q(1,2,1,"Alimony paid under a divorce agreement executed in 2023 is:","Not deductible by the payer and not taxable to the recipient",["Deductible by the payer and taxable to the recipient", "Taxable only if over $15,000", "Deductible as an itemized deduction"],"Post-2018 agreements: no deduction, no income.");
Q(1,2,1,"Which is included in gross income?","A painting received from a client in exchange for legal services",["A gift of stock from a parent", "Child support received", "Life insurance proceeds received after a parent's death"],"Property received for services is income at FMV (§61). Gifts, child support and death benefits are excluded.");
Q(1,2,1,"The Net Investment Income Tax may apply to which of the following?","A taxable mutual fund distribution",["A traditional IRA distribution","Tax-exempt municipal bond interest","Alimony"],"NII includes interest, dividends, capital gains, rents and passive income. Retirement distributions, municipal interest and alimony are excluded.");
Q(1,2,1,"Interest on qualified U.S. savings bonds may be excluded if the owner pays:","Qualified higher education expenses in the same year",["Mortgage interest on a rental", "Household employee wages paid over $1,000 in the year", "Government-subsidized rent"],"Under §135, interest on Series EE or I bonds can be excluded when it is used for qualified higher education expenses in the same year, subject to an income phaseout.");
Q(1,2,1,"What is the 2025 foreign earned income exclusion amount?","$130,000",["$126,500","$120,000","$135,000"],"$130,000 per qualifying individual for 2025.");
Q(1,2,1,"What was the 2025 Form 1099-K reporting threshold for payment apps and online marketplaces?","Over $20,000 and over 200 transactions",["$600 or more, with no transaction minimum", "$2,500", "$5,000"],"OBBBA restored the $20,000/200 threshold retroactively.");
Q(1,2,1,"An inherited asset is treated as held:","Long-term, regardless of how long the heir held it",["Short-term if the heir sells it within 1 year of death", "For the decedent's holding period", "Long-term only after 1 year"],"Inherited property always gets a long-term holding period.");
Q(1,2,1,"A 62-year-old taxpayer files MFS and lived apart from the spouse all year. The base amount for taxable Social Security is:","$25,000",["$0","$32,000","$9,000"],"MFS who lived apart the entire year use $25,000. MFS who lived together at any time use $0.");
Q(1,2,1,"Which is NOT included when calculating whether Social Security benefits are taxable?","Meals excluded from income under §119",["Tax-exempt interest","Foreign earned income excluded","Employer-provided adoption benefits excluded"],"Provisional income adds back tax-exempt interest and certain exclusions (FEIE, adoption benefits, savings bond interest), but not §119 meals.");
Q(1,2,2,"Ana received a $10,000 scholarship: $6,000 for tuition and required books, and $4,000 for room and board. She is a degree candidate. How much is taxable?","$4,000",["$0","$10,000","$6,000"],"Room and board are not qualified expenses for the scholarship exclusion.");
Q(1,2,2,"Which IRA distribution is subject to the 10% early withdrawal penalty?","A 45-year-old's distribution used to pay off credit card debt",["A 50-year-old's distribution for qualified higher education expenses","A 40-year-old's $10,000 first-time homebuyer distribution","A 35-year-old beneficiary's distribution from an inherited IRA"],"Debt payoff is not an exception. Education, first-time homebuyer and death are.");
Q(1,2,2,"Karen, 56, left her employer in 2025 and took a distribution from her 401(k). Is the 10% penalty due?","No, because she separated from service in or after the year she turned 55",["Yes, because she is under 59½", "No, but only if she rolls it into an IRA within 60 days of leaving", "Yes, unless she uses it for medical expenses"],"The age-55 separation exception applies to employer plans (not IRAs).");
Q(1,2,2,"Which correctly describes a wash sale?","A loss is disallowed if substantially identical stock is bought within 30 days before or after the sale",["A gain is deferred if stock is sold and repurchased within 60 days", "A loss is disallowed if the stock was held less than 1 year", "Any loss on stock sold to a relative is deferred until the relative later sells it to someone else"],"Wash sale: 61-day window. The disallowed loss is added to the basis of the replacement stock.");
Q(1,2,2,"Ken owned and lived in his home for 14 months, then sold it because his employer transferred him 300 miles away. His gain is $200,000. He is single. How much can he exclude?","$145,833",["$200,000","$250,000","$0"],"Reduced exclusion: 14/24 × $250,000 = $145,833. Gain above that is taxable.");
Q(1,2,2,"A non-spouse beneficiary (not an eligible designated beneficiary) inherits an IRA in 2025 from an owner who died in 2025. The account must be fully distributed by:","December 31, 2035",["December 31, 2030","The beneficiary's life expectancy","5 years after death"],"10-year rule: by the end of the 10th year following the year of death.");
Q(1,2,2,"Which is excluded from gross income?","Compensatory damages for a broken leg in a car accident",["Punitive damages from a lawsuit","Interest on a life insurance settlement","Damages for emotional distress not tied to physical injury"],"§104 excludes damages for personal physical injuries. Punitive damages and interest are taxable.");
Q(1,2,3,"Single taxpayer: Social Security benefits $20,000, pension $30,000, tax-exempt interest $2,000. How much of the benefits is taxable?","$11,300",["$17,000","$6,800","$10,000"],"Provisional income = 30,000 + 2,000 + 10,000 = 42,000. Tier 1 = lesser of 50% × (34,000 − 25,000) = 4,500 or 50% of benefits (10,000) → 4,500. Tier 2 = 85% × (42,000 − 34,000) = 6,800. Total 11,300, under the 85% cap of 17,000.");
Q(1,2,3,"Dad gave Sue stock with a basis of $10,000 and FMV of $7,000 on the date of the gift. Sue sold it for $8,000. Her gain or loss is:","$0",["$1,000 loss","$2,000 loss","$1,000 gain"],"Gain basis = $10,000 (no gain at $8,000). Loss basis = $7,000 (no loss at $8,000). A sale between the two gives no gain or loss.");
Q(1,2,3,"Same gift (donor basis $10,000, FMV $7,000 at gift). Sue sells for $6,000. Her result is:","$1,000 capital loss",["$4,000 capital loss","$0","$3,000 capital loss"],"For a loss, basis is the lower FMV of $7,000. $6,000 − $7,000 = $1,000 loss.");
Q(1,2,3,"Bill sold 100 shares at a $1,000 loss on Dec 10, 2025, and bought 100 shares of the same stock for $4,200 on Dec 28. His basis in the new shares is:","$5,200",["$4,200","$3,200","$4,200 plus a $1,000 capital loss"],"Wash sale: the $1,000 disallowed loss is added to the new basis: $4,200 + $1,000.");
Q(1,2,3,"2025 capital transactions: STCG $4,000, STCL $9,000, LTCG $2,000, LTCL $1,000. What is the result?","Deduct $3,000; carry over $1,000 short-term loss",["Deduct $4,000","Deduct $3,000; carry over $1,000 long-term loss","Deduct $5,000"],"Net short-term = −5,000. Net long-term = +1,000. Net = −4,000. Deduct 3,000; the remaining 1,000 is short-term because the net loss came from the short-term side.");
Q(1,2,3,"MFJ couple, MAGI $120,000, actively participate in a rental with a $30,000 loss and have no passive income. How much loss is deductible in 2025?","$15,000",["$25,000","$30,000","$0"],"Allowance $25,000 − 50% × ($120,000 − $100,000) = $15,000. The rest is suspended.");
Q(1,2,3,"Rita, 45, took $20,000 from her traditional IRA; $8,000 paid qualified college tuition for her son. Assuming all is taxable, her additional 10% tax is:","$1,200",["$2,000","$800","$0"],"Only the $12,000 not covered by the education exception is penalized: 10% × $12,000.");
Q(1,2,3,"Jon (single, all from one job) had $210,000 of wages and $40,000 of interest and dividends. What is his NIIT?","$1,520",["$1,900","$380","$0"],"NIIT = 3.8% × lesser of NII ($40,000) or MAGI over $200,000 ($50,000) = 3.8% × 40,000 = $1,520.");

// ---------- Domain 3: Deductions and credits ----------
F(1,3,"Educator expense deduction (2025)","Up to $300 per eligible educator ($600 if both spouses are educators, max $300 each); K-12, at least 900 hours");
F(1,3,"Student loan interest deduction","Up to $2,500; 2025 MAGI phase-out $85,000–$100,000 single, $170,000–$200,000 MFJ; not allowed MFS or if claimed as a dependent");
F(1,3,"2025 IRA contribution limit","$7,000 ($8,000 if 50 or older), limited to taxable compensation. Deadline: April 15, 2026 (no extension)");
F(1,3,"2025 traditional IRA deduction phase-out: covered by workplace plan","Single/HOH: $79,000–$89,000. MFJ (contributor covered): $126,000–$146,000. MFS: $0–$10,000");
F(1,3,"2025 IRA deduction phase-out: you're not covered, spouse is","MFJ: $236,000–$246,000");
F(1,3,"2025 Roth IRA contribution phase-out","Single/HOH: $150,000–$165,000. MFJ: $236,000–$246,000. MFS: $0–$10,000");
F(1,3,"Spousal IRA","A non-working spouse can contribute up to the limit based on the working spouse's compensation if MFJ");
F(1,3,"Self-employed adjustments to income","Deductible part (½) of SE tax; self-employed health insurance (not if eligible for an employer-subsidized plan); SEP, SIMPLE and solo 401(k) contributions");
F(1,3,"Moving expenses deduction","Only for active-duty military moving under orders to a permanent change of station");
F(1,3,"Penalty on early withdrawal of savings","Adjustment to income (Schedule 1)");
F(1,3,"New OBBBA deductions: where reported and who can claim","Schedule 1-A; taken whether or not you itemize; a married taxpayer must file jointly for the tips, overtime and senior deductions (not required for car loan interest)");
F(1,3,"Senior deduction (2025–2028)","$6,000 per person age 65+ by year end ($12,000 if both spouses qualify); reduced by 6% of MAGI over $75,000 ($150,000 MFJ); valid SSN required");
F(1,3,"Qualified tips deduction (2025–2028)","Up to $25,000; reduced by $100 per $1,000 of MAGI over $150,000 ($300,000 MFJ); occupations that customarily received tips; voluntary cash or charged tips; SSN required; tips still subject to FICA");
F(1,3,"Qualified overtime deduction (2025–2028)","Premium portion only (the 'half' in time-and-a-half) of FLSA-required overtime; up to $12,500 ($25,000 MFJ); same phase-out as tips ($150,000/$300,000)");
F(1,3,"Car loan interest deduction (2025–2028)","Up to $10,000 per year; new personal-use vehicle with final assembly in the U.S.; loan originated after Dec 31, 2024, secured by the vehicle; phase-out over $100,000 MAGI ($200,000 MFJ). No used cars or leases");
F(1,3,"Medical expense deduction floor","Only the amount over 7.5% of AGI");
F(1,3,"2025 standard mileage rates","Business 70¢; medical and military moving 21¢; charitable 14¢ per mile");
F(1,3,"2025 SALT deduction cap (OBBBA)","$40,000 ($20,000 MFS); reduced by 30% of MAGI over $500,000 ($250,000 MFS), but never below $10,000 ($5,000 MFS)");
F(1,3,"SALT: income tax vs sales tax","You may deduct state and local income taxes OR general sales taxes, not both. Foreign real property taxes are not deductible");
F(1,3,"Mortgage interest: acquisition debt limit","$750,000 ($375,000 MFS) for debt incurred after Dec 15, 2017; $1,000,000 grandfathered for older debt");
F(1,3,"Home equity loan interest","Deductible only if the loan proceeds were used to buy, build, or substantially improve the home securing the loan");
F(1,3,"Points on a home purchase loan","Generally deductible in the year paid for a main home. Points on a refinance are amortized over the loan term");
F(1,3,"Mortgage insurance premiums (2025)","Not deductible for 2025. They become deductible again starting in 2026 (trap)");
F(1,3,"Investment interest expense","Deductible up to net investment income (Form 4952); excess carries forward indefinitely");
F(1,3,"Charitable cash to public charities: AGI limit","60% of AGI; excess carries forward 5 years");
F(1,3,"Charitable: appreciated long-term capital gain property","Deduct FMV, limited to 30% of AGI (public charity); 20% for gifts to private non-operating foundations");
F(1,3,"Charitable substantiation thresholds","$250+: contemporaneous written acknowledgment. Noncash over $500: Form 8283. Over $5,000: qualified appraisal. Vehicle over $500: Form 1098-C. Quid pro quo over $75: charity must disclose");
F(1,3,"Value of volunteer services","Not deductible. Unreimbursed out-of-pocket costs and 14¢ per mile are deductible");
F(1,3,"Personal casualty and theft losses (2025)","Only losses from a federally declared disaster; reduce each loss by $100 and total by 10% of AGI. Form 4684");
F(1,3,"Qualified disaster loss","$500 floor per casualty, no 10% of AGI reduction, and can be added to the standard deduction");
F(1,3,"Miscellaneous itemized deductions subject to 2% (tax prep fees, unreimbursed employee expenses)","Not deductible, permanently (OBBBA)");
F(1,3,"2025 Child Tax Credit","$2,200 per qualifying child under 17 at year end; up to $1,700 refundable (ACTC)");
F(1,3,"CTC phase-out","Reduced $50 per $1,000 (or part) of MAGI over $200,000 ($400,000 MFJ)");
F(1,3,"CTC SSN rules (2025)","Child must have an SSN valid for employment issued by the return due date, and at least one parent (taxpayer or spouse) must have an SSN");
F(1,3,"Additional Child Tax Credit formula","15% of earned income over $2,500, up to $1,700 per child (2025)");
F(1,3,"Credit for Other Dependents","$500 nonrefundable: dependents who don't qualify for the CTC (age 17+, qualifying relatives, ITIN children)");
F(1,3,"American Opportunity Tax Credit (AOTC)","Up to $2,500 per student: 100% of first $2,000 + 25% of next $2,000. 40% refundable (up to $1,000)");
F(1,3,"AOTC eligibility","First 4 years of postsecondary education; at least half-time in a degree program; claimed no more than 4 tax years; no felony drug conviction");
F(1,3,"Lifetime Learning Credit","20% of up to $10,000 = $2,000 per return; nonrefundable; unlimited years; no half-time requirement");
F(1,3,"Education credit MAGI phase-out (AOTC and LLC)","$80,000–$90,000 single; $160,000–$180,000 MFJ");
F(1,3,"Education credits and MFS","Neither AOTC nor LLC is allowed on a Married Filing Separately return");
F(1,3,"AOTC: are books counted?","Yes, required books, supplies and equipment count even if not bought from the school (LLC only counts them if paid to the school)");
F(1,3,"2025 EITC maximum credit","No children $649; 1 child $4,328; 2 children $7,152; 3+ children $8,046");
F(1,3,"2025 EITC investment income limit","$11,950");
F(1,3,"EITC with no qualifying child: age","At least 25 and under 65 at year end; not a dependent; lived in U.S. over half the year");
F(1,3,"EITC after disallowance","Form 8862 to claim again. Ban of 2 years for reckless disregard, 10 years for fraud");
F(1,3,"EITC and MFS","Allowed only if you lived apart from your spouse the last 6 months of the year or have a separation agreement, and have a qualifying child");
F(1,3,"Child and dependent care credit (2025)","20%–35% of up to $3,000 (one person) or $6,000 (two or more) of expenses. Form 2441. Larger credit starts 2026 (trap)");
F(1,3,"Dependent care: qualifying person","Your dependent under 13, or a spouse or dependent physically or mentally unable to care for self who lived with you over half the year");
F(1,3,"Dependent care: earned income limit","Expenses limited to the lower-earning spouse's earned income. A full-time student or disabled spouse is deemed to earn $250/month (one person) or $500/month (two or more)");
F(1,3,"Dependent care: payments to relatives","Payments to your spouse, the child's parent, your dependent, or your child under 19 don't qualify");
F(1,3,"2025 saver's credit AGI limits","$39,500 single/MFS; $59,250 HOH; $79,000 MFJ. Credit rate 50%, 20% or 10% of up to $2,000 per person");
F(1,3,"Premium tax credit: forms","Form 1095-A (from the Marketplace) is used to complete Form 8962. Form 1095-A is not attached to the return");
F(1,3,"Premium tax credit: MFS","Generally not allowed, except for victims of domestic abuse or spousal abandonment");
F(1,3,"2025 adoption credit","Up to $17,280 per child; up to $5,000 refundable (new for 2025, OBBBA); phase-out begins at MAGI of $259,190");
F(1,3,"Residential clean energy credit (§25D)","30% of solar, wind, geothermal, battery storage costs. Ends for expenditures made after Dec 31, 2025 (still allowed for 2025)");
F(1,3,"Energy efficient home improvement credit (§25C)","30%, up to $1,200 per year ($2,000 for heat pumps). Ends for property placed in service after Dec 31, 2025");
F(1,3,"Clean vehicle credit (2025)","New EV up to $7,500; used EV up to $4,000. Not available for vehicles acquired after September 30, 2025");
F(1,3,"Foreign tax credit without Form 1116","Allowed if all foreign taxes are on passive income reported on 1099s and total ≤ $300 ($600 MFJ)");
F(1,3,"Credit for the elderly or disabled","Schedule R; age 65+ or retired on permanent and total disability; low income limits");
F(1,3,"Excess Social Security withheld","With two or more employers, Social Security tax withheld over the 2025 wage base ($176,100) is a refundable credit on Schedule 3");

Q(1,3,1,"For medical expenses to be deductible in 2025, they must exceed what percentage of AGI?","7.5%",["10%","2%","Medical expenses are no longer deductible"],"Only unreimbursed medical expenses above 7.5% of AGI can be deducted, and only if the taxpayer itemizes.");
Q(1,3,1,"Tax preparation fees for individuals for 2025 are:","Not deductible",["A miscellaneous itemized deduction subject to 2%","An adjustment on Schedule 1","An investment expense on Schedule A"],"Miscellaneous 2% itemized deductions are permanently eliminated.");
Q(1,3,1,"What is the 2025 SALT deduction cap for a married couple filing jointly with MAGI under $500,000?","$40,000",["$10,000","$20,000","$80,000"],"OBBBA raised the cap to $40,000 ($20,000 MFS) for 2025.");
Q(1,3,1,"If a dependent can't be claimed for the child tax credit, the dependent may qualify you for which $500 credit?","Credit for Other Dependents",["Alternative Minimum Tax Credit","Credit for Foreign Dependents","Additional Child Tax Credit"],"A dependent who doesn't qualify for the child tax credit (for example, age 17 or older, or a qualifying relative) can still bring the $500 credit for other dependents.");
Q(1,3,1,"What is the maximum 2025 child tax credit per qualifying child?","$2,200",["$2,000","$1,700","$3,000"],"OBBBA raised the CTC to $2,200; up to $1,700 is refundable.");
Q(1,3,1,"What is the maximum American Opportunity Tax Credit per student?","$2,500",["$2,000","$4,000","$1,000"],"100% of the first $2,000 plus 25% of the next $2,000.");
Q(1,3,1,"Which is true about the Lifetime Learning Credit?","It is 20% of up to $10,000 of expenses per return",["It is 40% refundable","It is limited to the first 4 years of college","It requires at least half-time enrollment"],"LLC: max $2,000 per return, nonrefundable, unlimited years.");
Q(1,3,1,"Which form is used to complete Form 8962, Premium Tax Credit?","Form 1095-A",["Form 1095-C","Form 1098-T","Form 1099-G"],"Form 1095-A from the Marketplace provides premiums and advance payments. It isn't attached to the return.");
Q(1,3,1,"Which is true regarding the premium tax credit?","No PTC is allowed for any period an individual is not lawfully present in the U.S.",["Married individuals must always file jointly, with no exceptions at all", "Coverage for at least 6 months is required", "Form 1095-A is not needed"],"IRC §36B(e). MFS exceptions exist for domestic abuse and abandonment.");
Q(1,3,1,"Where are the new 2025 deductions for tips, overtime, car loan interest and seniors reported?","Schedule 1-A",["Schedule A", "Schedule C", "Form 8995"],"They're on Schedule 1-A and available to both itemizers and non-itemizers.");
Q(1,3,1,"Which is a requirement to claim the 2025 senior deduction?","Age 65 or older by the end of the year",["Itemizing deductions","Receiving Social Security benefits","Filing as Single"],"$6,000 per qualifying person age 65+; married couples must file jointly.");
Q(1,3,1,"Which loan qualifies for the car loan interest deduction?","A 2025 loan for a new personal-use car assembled in the U.S.",["A 2025 lease of a new car", "A 2025 loan for a used car that was assembled in the U.S.", "A 2023 loan for a new car"],"New vehicle, final U.S. assembly, loan originated after 2024, personal use.");
Q(1,3,1,"The 2025 earned income credit investment income limit is:","$11,950",["$11,600","$10,000","$3,650"],"Investment income over $11,950 disqualifies the taxpayer.");
Q(1,3,2,"Two taxpayers married on November 30. The husband enrolled in college and received a 1098-T. The wife earned $45,000 and paid his tuition. What is correct?","They must file jointly to claim an education credit",["Based on the wife's AGI, they don't qualify","The husband is ineligible because his wife paid","The wife reports nonqualified expenses on Form 8863"],"Education credits are not allowed for MFS (§25A(g)(6)).");
Q(1,3,2,"For which work does the overtime deduction apply?","The premium part of overtime required by the Fair Labor Standards Act",["All wages for hours over 40","Overtime paid under a union contract that the FLSA doesn't require","Holiday pay at straight time"],"Only the FLSA-required premium portion of overtime qualifies.");
Q(1,3,2,"Which charitable deduction is allowed for 2025 for a taxpayer who takes the standard deduction?","None",["Up to $1,000 of cash gifts","Up to $300 of cash gifts","Up to 60% of AGI"],"The non-itemizer deduction ($1,000/$2,000) starts in 2026. For 2025 there is none.");
Q(1,3,2,"Which is correct regarding a personal casualty loss in 2025?","Loss from progressive deterioration, such as termites, is not deductible",["It is reduced by the standard deduction before the AGI limit", "It must be less than 10% of AGI", "It is deducted over 3 years"],"A casualty must be sudden, unexpected or unusual and (2025) in a federally declared disaster area.");
Q(1,3,2,"A couple borrowed $100,000 on a home equity line and used it to pay off credit cards and buy a car. The interest is:","Not deductible",["Deductible up to $100,000 of debt","Deductible as investment interest","Deductible only if they itemize and the house is their main home"],"Home equity interest is deductible only if used to buy, build, or substantially improve the home.");
Q(1,3,2,"Which person can be a qualifying person for the child and dependent care credit?","A 12-year-old dependent child",["A 13-year-old dependent child","The taxpayer's 18-year-old who babysits","A healthy spouse"],"Under age 13, or a dependent/spouse incapable of self-care.");
Q(1,3,2,"An AOTC claim requires the student to:","Be enrolled at least half-time in a degree program for at least one academic period",["Be in graduate school", "Be under age 24", "Have no other scholarships or grants of any kind during the year"],"AOTC: first 4 years, at least half-time, no felony drug conviction.");
Q(1,3,3,"MFJ, AGI $60,000, unreimbursed medical expenses $7,000. Their deductible medical expense is:","$2,500",["$7,000","$4,500","$1,000"],"$7,000 − (7.5% × $60,000 = $4,500) = $2,500.");
Q(1,3,3,"MFJ, MAGI $560,000, paid $45,000 of state income and property taxes in 2025. Their SALT deduction is:","$22,000",["$40,000","$10,000","$45,000"],"Cap $40,000 − 30% × ($560,000 − $500,000) = $40,000 − $18,000 = $22,000 (above the $10,000 floor).");
Q(1,3,3,"Single, age 66, MAGI $95,000. What is the 2025 senior deduction?","$4,800",["$6,000","$1,200","$0"],"$6,000 − 6% × ($95,000 − $75,000) = $6,000 − $1,200 = $4,800.");
Q(1,3,3,"MFJ with 2 qualifying children, MAGI $410,000. Their 2025 child tax credit is:","$3,900",["$4,400","$4,000","$3,400"],"$4,400 − $50 × 10 (each $1,000 over $400,000) = $3,900.");
Q(1,3,3,"Tuition $3,000 and required books $400 for a freshman. The AOTC and its refundable portion are:","$2,350 credit; $940 refundable",["$2,500 credit; $1,000 refundable", "$2,000; $800 refundable", "$2,350; $1,000 refundable"],"100% × 2,000 + 25% × 1,400 = 2,350. Refundable 40% = 940.");
Q(1,3,3,"Single, AGI $100,000, home damaged in a federally declared disaster (not a qualified disaster). Decline in FMV $30,000 (less than basis), insurance $10,000. Deductible loss:","$9,900",["$20,000","$19,900","$10,000"],"($30,000 − $10,000) − $100 − 10% × $100,000 = $9,900.");
Q(1,3,3,"Single, AGI $20,000, gave stock held 3 years (basis $2,000, FMV $10,000) to a public charity. 2025 deduction and carryover:","$6,000 deduction; $4,000 carried forward",["$10,000; none", "$2,000; none", "$12,000 deduction; nothing carried"],"FMV deduction limited to 30% of AGI = $6,000; excess carries forward 5 years.");
Q(1,3,3,"A 2025 itemizer had $5,000 of gambling winnings and $7,000 of gambling losses. Deductible losses:","$5,000",["$7,000","$4,500","$0"],"2025 losses are deductible up to winnings. The 90% limit starts in 2026.");
Q(1,3,3,"Single tipped worker, MAGI $170,000, qualified tips $20,000. 2025 tips deduction:","$18,000",["$20,000","$25,000","$0"],"Reduced $100 per $1,000 over $150,000: 20 × $100 = $2,000. $20,000 − $2,000 = $18,000.");

// ---------- Domain 4: Taxation ----------
F(1,4,"2025 tax brackets: Single","10% to $11,925; 12% to $48,475; 22% to $103,350; 24% to $197,300; 32% to $250,525; 35% to $626,350; 37% above");
F(1,4,"2025 tax brackets: MFJ","10% to $23,850; 12% to $96,950; 22% to $206,700; 24% to $394,600; 32% to $501,050; 35% to $751,600; 37% above");
F(1,4,"Kiddie tax: 2025 threshold","Child's unearned income over $2,700 is taxed at the parent's rate (first $1,350 tax-free, next $1,350 at child's rate)");
F(1,4,"Kiddie tax applies to","Children under 18; age 18 or full-time students 19–23 whose earned income is not more than half their support; at least one parent alive; child not filing jointly");
F(1,4,"Form 8615","Tax for certain children who have unearned income (kiddie tax)");
F(1,4,"Form 8814","Parent's election to report child's interest and dividends: child's income only interest, dividends and capital gain distributions, gross income under $13,500 (2025), no estimated payments or withholding");
F(1,4,"2025 AMT exemption","$88,100 Single/HOH; $137,000 MFJ; $68,500 MFS");
F(1,4,"2025 AMT exemption phase-out starts","$626,350 Single; $1,252,700 MFJ (25 cents per dollar)");
F(1,4,"AMT rates","26% and 28% (28% on AMT base over $239,100; $119,550 MFS for 2025)");
F(1,4,"Common AMT adjustments and preferences","SALT and standard deduction not allowed; ISO bargain element; private activity bond interest; accelerated depreciation differences");
F(1,4,"Self-employment tax","15.3% (12.4% Social Security + 2.9% Medicare) on 92.35% of net SE earnings. Social Security part only up to the 2025 wage base of $176,100 less W-2 wages");
F(1,4,"Deduction for SE tax","One-half of SE tax is an adjustment to income");
F(1,4,"Additional Medicare Tax","0.9% on wages/SE income over $200,000 Single/HOH, $250,000 MFJ, $125,000 MFS. Employers withhold on wages over $200,000 regardless of status. Form 8959");
F(1,4,"Who must pay estimated tax","Expect to owe $1,000 or more after withholding and credits");
F(1,4,"Estimated tax safe harbors","Pay the smaller of 90% of current-year tax or 100% of prior-year tax (110% if prior-year AGI over $150,000; $75,000 MFS)");
F(1,4,"2025 estimated tax due dates","April 15, June 16 (June 15 fell on a Sunday), September 15, 2025, and January 15, 2026");
F(1,4,"Farmers and fishermen estimated tax","Two-thirds of gross income from farming/fishing: pay 66⅔% by January 15, or file and pay all tax by March 1");
F(1,4,"Form 2210","Underpayment of estimated tax by individuals");
F(1,4,"Failure-to-file penalty","5% of unpaid tax per month or part of a month, max 25%. Fraudulent: 15% per month, max 75%");
F(1,4,"Failure-to-pay penalty","0.5% of unpaid tax per month, max 25%. Reduced to 0.25% during an installment agreement (timely filed return). Increases to 1% after a notice of intent to levy");
F(1,4,"When both FTF and FTP apply in the same month","FTF is reduced by the FTP, so the combined rate is 5% per month");
F(1,4,"Accuracy-related penalty","20% of the underpayment due to negligence or substantial understatement (individual: over the greater of 10% of correct tax or $5,000)");
F(1,4,"Household employer: when Schedule H is needed (2025)","Cash wages of $2,800 or more to any one household employee (Social Security/Medicare), or $1,000+ in any quarter to all household employees (FUTA)");
F(1,4,"Underpayment interest rate (individuals)","Federal short-term rate + 3%, compounded daily");

Q(1,4,1,"A child may be subject to the kiddie tax for 2025 if:","The child is under age 18 at the end of the year",["Neither parent is alive at year end", "The child has only nontaxable income for the year", "The child files a joint return"],"§1(g)(2). Also applies to some 18-year-olds and full-time students under 24.");
Q(1,4,1,"For 2025, a child's unearned income over what amount is taxed at the parent's rate?","$2,700",["$2,600","$1,350","$13,500"],"$1,350 tax-free + $1,350 at child's rate; the rest at parent's rate.");
Q(1,4,1,"Self-employment tax is computed on what percentage of net earnings?","92.35%",["100.0%", "85%", "50%"],"Net earnings × 92.35% × 15.3%.");
Q(1,4,1,"What is the 2025 Social Security wage base?","$176,100",["$168,600","$160,200","$180,000"],"The 12.4% Social Security portion stops at $176,100.");
Q(1,4,1,"The Additional Medicare Tax threshold for MFJ is:","$250,000",["$200,000","$125,000","$300,000"],"$200,000 Single/HOH, $250,000 MFJ, $125,000 MFS.");
Q(1,4,1,"What is the failure-to-file penalty rate?","5% per month, up to 25%",["0.5% per month, up to 25%","1% per month, up to 50%","10% flat"],"FTF: 5%/month, max 25%. FTP: 0.5%/month, max 25%.");
Q(1,4,1,"Which form reports the kiddie tax?","Form 8615",["Form 8814","Form 6251","Form 2210"],"8615 is filed with the child's return. 8814 is the parent's election.");
Q(1,4,2,"Which item is an AMT adjustment for an individual?","State and local income taxes deducted on Schedule A",["Mortgage interest on a main home", "Charitable contributions", "Medical expenses over 7.5% of AGI on Schedule A"],"SALT is added back for AMT; the standard deduction is also not allowed.");
Q(1,4,2,"Who may use the 2-thirds / January 15 estimated tax rule?","A farmer whose farm income is at least two-thirds of total gross income",["Any taxpayer with self-employment income from any trade or business", "Retirees with Social Security only", "Taxpayers whose prior-year tax was zero"],"Farmers and fishermen: pay 66⅔% by Jan 15, or file and pay all by March 1.");
Q(1,4,2,"A taxpayer with a 2025 installment agreement who filed on time pays what failure-to-pay penalty rate during the agreement?","0.25% per month",["0.5% per month","1% per month","No penalty"],"The FTP rate drops to 0.25% while an installment agreement is in effect.");
Q(1,4,3,"Prior-year AGI $180,000 and tax $30,000; expected 2025 tax $40,000. Minimum 2025 estimated payments to avoid the penalty:","$33,000",["$36,000","$30,000","$40,000"],"Lesser of 90% × 40,000 = 36,000 or 110% × 30,000 = 33,000 (prior AGI over $150,000).");
Q(1,4,3,"Sole proprietor net profit $50,000 (no wages). SE tax and the deduction for half of it are about:","$7,065 SE tax; $3,532 deduction",["$7,650 SE tax; $3,825 deduction", "$7,065; $7,065", "$6,525; $3,262"],"$50,000 × 92.35% = $46,175 × 15.3% = $7,064.78. Half ≈ $3,532.");
Q(1,4,3,"A 15-year-old has $5,000 of interest income and no earned income in 2025. How much is taxed at the parents' rate?","$2,300",["$3,650","$5,000","$2,700"],"$5,000 − $2,700 = $2,300.");
Q(1,4,3,"A return showing $10,000 tax due is filed 3 months late without extension; tax unpaid. Combined FTF + FTP penalty (ignore minimums):","$1,500",["$1,650","$1,350","$500"],"Each month: FTP 0.5% + FTF reduced to 4.5% = 5% × 3 months = 15% × $10,000.");

// ---------- Domain 5: Advising the individual ----------
F(1,5,"How long to keep tax records","Generally 3 years from filing; 6 years if income was underreported by more than 25%; 7 years for bad debt or worthless securities claims; indefinitely if no return or fraud; property records until the period for the year of disposition ends");
F(1,5,"Employment tax records","Keep at least 4 years");
F(1,5,"Refund claim deadline","Later of 3 years from when the return was filed or 2 years from when the tax was paid");
F(1,5,"Amended individual return","Form 1040-X (can be e-filed)");
F(1,5,"Innocent spouse relief","Form 8857. Relief from joint-return liability for the other spouse's errors. Under §6015(b) and (c), request within 2 years of the IRS's first collection activity");
F(1,5,"Injured spouse allocation","Form 8379. Recovers your share of a joint refund taken to pay your spouse's past-due debt (child support, student loans, other taxes)");
F(1,5,"Property transfers between spouses or incident to divorce (§1041)","No gain or loss; the receiving spouse takes the transferor's basis");
F(1,5,"Roth conversion: tax effect","Converted pre-tax amount is taxable income in the year of conversion but is not subject to the 10% penalty");
F(1,5,"Name change after marriage","Notify the Social Security Administration before filing so the name matches the SSN");
F(1,5,"Withholding adjustment form","Form W-4 to employer (W-4P / W-4R for pensions and other payments)");
F(1,5,"Divorce in 2025: filing status","If divorced by Dec 31, you are unmarried for the whole year (Single or HOH)");

Q(1,5,1,"Generally, how long should a taxpayer keep records supporting a return?","3 years from the date the return was filed",["1 year", "7 years in all cases", "Only until the next year's return is filed"],"6 years for 25% omissions; 7 years for bad debts/worthless securities.");
Q(1,5,1,"Which form is used to request innocent spouse relief?","Form 8857",["Form 8379","Form 8332","Form 1040-X"],"Form 8857 requests innocent spouse relief from a joint tax debt. Don't confuse it with Form 8379, the injured spouse form used to get back a share of an offset refund.");
Q(1,5,2,"A taxpayer's joint refund was offset for her husband's past-due child support. She had all the income and withholding. She should file:","Form 8379, Injured Spouse Allocation",["Form 8857, innocent spouse relief","Form 843, claim for refund","Form 1040-X as MFS"],"Injured spouse recovers her share of the refund.");
Q(1,5,2,"In 2025, as part of a divorce, Joe transfers stock (basis $20,000, FMV $50,000) to his ex-wife. What are the tax results?","No gain to Joe; ex-wife's basis is $20,000",["Joe recognizes $30,000 gain; her basis is $50,000","No gain to Joe; her basis is $50,000","Joe has $30,000 of alimony income"],"§1041: treated like a gift; carryover basis.");
Q(1,5,3,"A 2024 return (due April 15, 2025) was filed early on February 20, 2025, with withholding covering the tax. The last day to file a refund claim is:","April 15, 2028",["February 20, 2028","April 15, 2027","October 15, 2028"],"A return filed early is treated as filed on its due date. 3 years from April 15, 2025 = April 15, 2028. Withholding is treated as paid on the due date.");

// ---------- Domain 6: Specialized returns for individuals ----------
F(1,6,"2025 gift tax annual exclusion","$19,000 per recipient ($38,000 with gift splitting)");
F(1,6,"2025 lifetime estate and gift exemption","$13,990,000 per person. Rises to $15,000,000 in 2026 (trap)");
F(1,6,"Gifts to a non-citizen spouse (2025)","Annual exclusion of $190,000 (unlimited marital deduction only for a U.S. citizen spouse)");
F(1,6,"Gifts that are excluded no matter the amount","Tuition paid directly to a school; medical expenses paid directly to the provider; gifts to a U.S. citizen spouse; gifts to charity; gifts to political organizations");
F(1,6,"Form 709 due date","April 15 of the year after the gift (extended with Form 4868 or Form 8892)");
F(1,6,"Gift splitting","Spouses elect to treat each gift as made half by each; requires filing Form 709 even if each half is under the exclusion");
F(1,6,"Form 706 due date","9 months after date of death; 6-month extension with Form 4768");
F(1,6,"Portability (DSUE)","Surviving spouse can use the deceased spouse's unused exemption if a timely Form 706 is filed (simplified late election available up to 5 years after death)");
F(1,6,"Alternate valuation date","6 months after death; may be elected only if it reduces both the gross estate and the estate tax");
F(1,6,"Final return of a decedent","Form 1040 due the normal due date of the following year; a surviving spouse may file jointly for the year of death; Form 1310 for a refund (not needed for a surviving spouse filing jointly)");
F(1,6,"Form 56","Notice of fiduciary relationship (executor, administrator, trustee)");
F(1,6,"Estate income tax return threshold","Form 1041 required if the estate has gross income of $600 or more");
F(1,6,"FBAR filing requirement","U.S. person with financial interest in or signature authority over foreign accounts whose aggregate value exceeded $10,000 at any time during the year");
F(1,6,"FBAR: form, where, when","FinCEN Form 114, filed electronically with FinCEN (not with the tax return). Due April 15; automatic extension to October 15");
F(1,6,"Form 8938 thresholds (U.S. residents)","Single/MFS: over $50,000 on the last day of the year or $75,000 at any time. MFJ: over $100,000 / $150,000");
F(1,6,"Form 8938 thresholds (living abroad)","Single: over $200,000 at year end or $300,000 any time. MFJ: over $400,000 / $600,000");
F(1,6,"Form 8938 vs FBAR","Form 8938 is attached to the income tax return (FATCA). Filing 8938 does not relieve you of filing the FBAR. Not required if you don't have to file a return");
F(1,6,"Substantial presence test","At least 31 days this year and 183 days total counting all days this year + 1/3 of last year + 1/6 of the year before");
F(1,6,"Exempt individuals (days don't count)","Foreign government officials; F/J/M/Q students (generally 5 calendar years); J/Q teachers and trainees (2 of last 6 years); professional athletes at charity events. Form 8843");
F(1,6,"Form 1040-NR","U.S. return for nonresident aliens. No standard deduction (except students/apprentices from India), generally can't file jointly");
F(1,6,"Nonresident alien income tax rules","Effectively connected income (ECI) taxed at graduated rates; fixed or determinable (FDAP) U.S.-source income taxed at a flat 30% unless a treaty reduces it");
F(1,6,"Dual-status alien","Resident part of the year and nonresident the rest. Can't use the standard deduction or file jointly unless electing to be treated as resident all year with a spouse");
F(1,6,"Form 8833","Treaty-based return position disclosure");
F(1,6,"Form 8840","Closer connection exception statement for aliens");
F(1,6,"ITIN expiration","An ITIN expires if not used on a federal return for 3 consecutive years");
F(1,6,"Income in respect of a decedent (IRD)","Income the decedent earned but hadn't received (final wages, IRA balances); taxed to whoever receives it with the same character; §691(c) deduction for estate tax attributable");

Q(1,6,1,"What is the 2025 annual gift tax exclusion per recipient?","$19,000",["$18,000","$17,000","$38,000"],"For 2025, each donor can give up to $19,000 to each person without using lifetime exemption or filing Form 709 (if no future interest or gift splitting is involved).");
Q(1,6,1,"What is the 2025 lifetime estate and gift tax exemption?","$13,990,000",["$15,000,000","$13,610,000","$12,920,000"],"$15,000,000 starts in 2026.");
Q(1,6,1,"Which is true regarding the FBAR?","FinCEN Form 114 is filed online with the Financial Crimes Enforcement Network",["It is due July 15", "It is filed with the income tax return as an attachment to Form 1040", "No automatic extension is available"],"Due April 15 with an automatic extension to October 15.");
Q(1,6,1,"An FBAR is required when the aggregate value of foreign accounts exceeds what amount at any time during the year?","$10,000",["$50,000","$75,000","$100,000"],"Aggregate maximum value over $10,000.");
Q(1,6,1,"Which is a correct statement about Form 8938?","It is attached to the annual return and filed by the due date, including extensions",["It is required even if no income tax return is required for the year", "Assets are reported only if they affect tax liability", "Filing it relieves the FBAR requirement"],"8938 goes with the return; no return required → no 8938.");
Q(1,6,1,"Form 706 is due:","9 months after the date of death",["April 15 of the year after death","6 months after death","With the decedent's final Form 1040"],"Extension of 6 months with Form 4768.");
Q(1,6,2,"Which gift requires a gift tax return even though no tax is due?","A married couple elects gift splitting for a $30,000 gift to their son",["$19,000 cash to a friend","Paying a grandchild's $40,000 tuition directly to the university","$100,000 to a U.S. citizen spouse"],"Gift splitting must be elected on Form 709.");
Q(1,6,2,"A foreign student on an F visa in her 3rd year in the U.S. is generally:","An exempt individual whose days don't count for the substantial presence test",["A resident alien, because she is present over 183 days in the year", "A dual-status alien", "Required to file Form 1040 as a resident"],"Students are generally exempt for 5 calendar years. They file Form 8843.");
Q(1,6,2,"U.S.-source dividends paid to a nonresident alien (no treaty) are generally taxed at:","A flat 30%",["Graduated rates","0%","15%"],"FDAP income: 30% withholding unless reduced by treaty.");
Q(1,6,3,"Days in the U.S.: 2025 120, 2024 150, 2023 180. Does the person meet the substantial presence test for 2025?","Yes, 200 weighted days",["No, only 120 days in 2025","No, 170 weighted days","Yes, 450 total days"],"120 + 150/3 (50) + 180/6 (30) = 200 ≥ 183, and ≥ 31 days in 2025.");
Q(1,6,3,"Single U.S. resident had foreign accounts with $45,000 at year end and $80,000 maximum during 2025. Which filings are required?","Both FBAR and Form 8938",["FBAR only", "FBAR only, never 8938", "Neither"],"FBAR: over $10,000. 8938: over $75,000 at any time for a single U.S. resident.");
Q(1,6,3,"A married couple wants to give their daughter as much cash as possible in 2025 without using any lifetime exemption. The maximum is:","$38,000",["$19,000","$76,000","$190,000"],"Two annual exclusions × $19,000 = $38,000 (one from each spouse, or by gift splitting on Form 709). Paying tuition directly to a school would be unlimited, but cash gifts are not.");
Q(1,6,3,"Grandma pays her grandson's $45,000 college tuition directly to the university and gives him $19,000 cash in 2025. Taxable gifts:","$0",["$45,000","$26,000","$64,000"],"Tuition paid directly to the school is excluded without limit, and the $19,000 cash is covered by the annual exclusion.");
